    window.erpApp.pmOpenEditContractedExpenseModal = (id) => {
        window.erpApp.pmOpenAddContractedExpenseModal(id);
    };

    window.erpApp.pmSaveContractedExpenseRecord = async (e, editId = null) => {
        e.preventDefault();
        const form = e.target;
        const formData = new FormData(form);
        const cleanNum = (str) => window.erpApp.parseVND(str);

        const voucherItems = document.querySelectorAll('#pmTempFilePreview .pm-file-item');
        const vouchers = Array.from(voucherItems).map(item => ({
            name: item.dataset.fileName,
            type: item.dataset.fileType,
            data: item.dataset.fileData
        }));

        const contractData = {
            id: formData.get('id'),
            projectId: pmActiveProjectId,
            type: 'inbound', // Force inbound for contracted expenses
            title: formData.get('title'),
            contractNo: formData.get('contractNo'),
            value: cleanNum(formData.get('value')),
            signDate: window.erpApp.parseInputDate(formData.get('signDate')),
            partner: formData.get('partner'),
            status: formData.get('status'),
            category: formData.get('category'),
            retentionRate: parseFloat(formData.get('retentionRate')) || 0,
            acceptanceRate: parseFloat(formData.get('acceptanceRate')) || 0,
            isContracted: true, // Flag for contracted agreements
            vouchers: vouchers
        };

        if (editId) {
            const idx = pmContracts.findIndex(c => c.id === editId);
            if (idx !== -1) {
                pmContracts[idx] = { ...pmContracts[idx], ...contractData };
            }
        } else {
            // Check for duplicate ID
            if (pmContracts.some(c => c.id === contractData.id)) {
                showToast('Mã hợp đồng đã tồn tại!', 'error');
                return;
            }
            pmContracts.unshift(contractData);
        }

        // 🔄 Sync with Archive Module
        const project = pmProjects.find(p => p.id === pmActiveProjectId);
        const projectName = project ? project.name : pmActiveProjectId;

        let hsDoc = hoSoDocuments.find(d => d.linkedPmId === contractData.id);
        const isNewDoc = !hsDoc;

        if (isNewDoc) {
            const nextId = (typeof window.erpApp.nextHsIdForContract === 'function') ? window.erpApp.nextHsIdForContract(contractData.id, projectName) : `HS-K-${Date.now().toString().slice(-4)}`;
            hsDoc = {
                id: nextId,
                files: []
            };
        }

        Object.assign(hsDoc, {
            title: contractData.title,
            category: 'hop-dong-khoan',
            project: projectName,
            department: 'Phòng Kỹ thuật',
            supplier: contractData.partner,
            customer: 'VIETBACHCORP',
            value: contractData.value,
            issueDate: contractData.signDate,
            status: 'active',
            note: `Liên kết từ HĐ Khoán nhân công ${contractData.id}`,
            linkedPmId: contractData.id
        });

        if (contractData.vouchers && contractData.vouchers.length > 0) {
            hsDoc.files = [...(hsDoc.files || []), ...contractData.vouchers];
        }

        if (isNewDoc) {
            hoSoDocuments.unshift(hsDoc);
        }

        contractData.linkedHsId = hsDoc.id;

        if (window.CrudSync) {
            window.CrudSync.saveItem('pmContracts', contractData, 'id')
                .catch(err => console.error('Error syncing labor contract:', err));
            window.CrudSync.saveItem('hoSoDocuments', hsDoc, 'id')
                .catch(err => console.error('Error syncing archive document:', err));
        }

        localStorage.setItem('erp_pmContracts', JSON.stringify(pmContracts));
        localStorage.setItem('erp_hoSoDocuments', JSON.stringify(hoSoDocuments));

        form.closest('.modal-overlay').remove();
        showToast(editId ? 'Cập nhật thành công!' : 'Thêm mới thành công!', 'success');

        if ((window.erpApp.currentPage === 'quan-ly-du-an' || window.erpApp.currentPage === 'van-hanh') && (pmActiveTab === 'labor' && pmLaborView === 'subcontracting')) {
            if (typeof renderQuanLyDuAn === 'function') renderQuanLyDuAn();
        }

        if (window.erpApp.notifyCRUD) {
            window.erpApp.notifyCRUD('Hợp đồng khoán', editId ? 'update' : 'add', {
                name: contractData.title,
                page: 'quan-ly-du-an',
                module: 'Chi phí khoán',
                projectId: pmActiveProjectId
            });
        }
    };

    window.erpApp.pmSyncLaborToArchive = async () => {
        const activeProjectId = pmActiveProjectId;
        if (!activeProjectId) {
            showToast('Vui lòng chọn một dự án để đồng bộ!', 'warning');
            return;
        }

        const project = pmProjects.find(p => p.id === activeProjectId);
        const projectName = project ? project.name : activeProjectId;
        const laborContracts = pmContracts.filter(c => c.projectId === activeProjectId && c.isContracted);

        if (laborContracts.length === 0) {
            showToast('Không có gói khoán nào trong dự án này để đồng bộ.', 'info');
            return;
        }

        let createdCount = 0;
        let updatedCount = 0;

        for (const contract of laborContracts) {
            let hsDoc = hoSoDocuments.find(d => d.linkedPmId === contract.id);
            const isNew = !hsDoc;

            if (isNew) {
                const nextId = (typeof window.erpApp.nextHsIdForContract === 'function') ? window.erpApp.nextHsIdForContract(contract.id, projectName) : `HS-K-${Date.now().toString().slice(-4)}`;
                hsDoc = { id: nextId, files: [] };
                hoSoDocuments.unshift(hsDoc);
                contract.linkedHsId = nextId;
                createdCount++;
            } else {
                updatedCount++;
            }

            Object.assign(hsDoc, {
                title: contract.title,
                category: 'hop-dong-khoan',
                project: projectName,
                department: 'Phòng Kỹ thuật',
                supplier: contract.partner,
                customer: 'VIETBACHCORP',
                value: contract.value,
                issueDate: contract.signDate,
                status: 'active',
                note: `Đồng bộ cưỡng bức từ HĐ Khoán dự án ${contract.id}`,
                linkedPmId: contract.id
            });

            if (window.CrudSync) {
                await window.CrudSync.saveItem('hoSoDocuments', hsDoc, 'id');
                await window.CrudSync.saveItem('pmContracts', contract, 'id');
            }
        }

        localStorage.setItem('erp_hoSoDocuments', JSON.stringify(hoSoDocuments));
        localStorage.setItem('erp_pmContracts', JSON.stringify(pmContracts));

        showToast(`Đồng bộ hoàn tất: Tạo mới ${createdCount}, Cập nhật ${updatedCount} hồ sơ.`, 'success');
        if (typeof renderQuanLyDuAn === 'function') renderQuanLyDuAn();
    };

    window.erpApp.pmReconcileLaborFromArchive = async () => {
        const activeProjectId = pmActiveProjectId;
        if (!activeProjectId) return;

        const project = pmProjects.find(p => p.id === activeProjectId);
        if (!project) return;

        const laborDocs = hoSoDocuments.filter(d => isProjectMatch(d.project, project) && d.category === 'hop-dong-khoan');
        let updateCount = 0;

        for (const doc of laborDocs) {
            if (doc.linkedPmId) {
                const contract = pmContracts.find(c => c.id === doc.linkedPmId);
                if (contract) {
                    let changed = false;
                    if (contract.title !== doc.title) { contract.title = doc.title; changed = true; }
                    if (contract.value !== doc.value) { contract.value = doc.value; changed = true; }
                    if (contract.partner !== doc.supplier) { contract.partner = doc.supplier; changed = true; }

                    if (changed) {
                        updateCount++;
                        if (window.CrudSync) await window.CrudSync.saveItem('pmContracts', contract, 'id');
                    }
                }
            }
        }

        if (updateCount > 0) {
            localStorage.setItem('erp_pmContracts', JSON.stringify(pmContracts));
            showToast(`Đã cập nhật ${updateCount} gói khoán từ Lưu trữ hồ sơ.`, 'success');
            if (typeof renderQuanLyDuAn === 'function') renderQuanLyDuAn();
        }
    };

    window.erpApp.pmDeleteContractedExpenseRecord = async (id) => {
        if (!window.currentUser || window.currentUser.role !== 'Admin') {
            showToast('Chỉ Admin mới có quyền xóa chi phí khoán!', 'error');
            return;
        }

        const record = pmContractedExpenses.find(r => r.id === id);
        if (!record) return;

        window.erpApp.showDeleteConfirmation(
            `Bạn có chắc chắn muốn xóa chi phí khoán <strong>${record.content || id}</strong>? Thao tác này không thể hoàn tác.`,
            async function () {
                const idx = pmContractedExpenses.findIndex(r => r.id === id);
                if (idx !== -1) {
                    const deleted = pmContractedExpenses.splice(idx, 1)[0];
                    if (window.CrudSync && typeof window.CrudSync.deleteItem === 'function') {
                        await window.CrudSync.deleteItem('pmContractedExpenses', id, 'id');
                    }
                    localStorage.setItem('erp_pmContractedExpenses', JSON.stringify(pmContractedExpenses));
                    showToast(`Đã xóa chi phí khoán thành công`, 'success');

                    if (window.erpApp.notifyCRUD) {
                        window.erpApp.notifyCRUD('Chi phí khoán', 'delete', {
                            name: deleted.content,
                            page: 'quan-ly-du-an',
                            module: 'Chi phí khoán',
                            projectId: pmActiveProjectId
                        });
                    }

                    if ((window.erpApp.currentPage === 'quan-ly-du-an' || window.erpApp.currentPage === 'van-hanh') && pmActiveTab === 'labor') {
                        if (typeof renderQuanLyDuAn === 'function') renderQuanLyDuAn();
                    }
                }
            }
        );
    };

