    window.erpApp.pmSaveTeam = (e) => {
        e.preventDefault();
        const formData = new FormData(e.target);
        const newTeam = {
            id: 'TEAM-' + Date.now().toString().slice(-4),
            name: formData.get('name'),
            leader: formData.get('leader'),
            contact: formData.get('contact'),
            projectId: pmActiveProjectId
        };
        pmTeams.push(newTeam);
        if (window.CrudSync) { window.CrudSync.saveItem('pmTeams', newTeam, 'id'); }
        localStorage.setItem('erp_pmTeams', JSON.stringify(pmTeams));

        // Also add a placeholder log for this team so they show up in the list
        const initialLog = {
            date: new Date().toISOString().split('T')[0],
            projectId: pmActiveProjectId,
            team: newTeam.name,
            count: 0,
            work: 'Vừa đăng ký tổ đội',
            manager: newTeam.leader
        };
        pmLaborLogs.push(initialLog);
        if (window.CrudSync) { window.CrudSync.saveItem('pmLaborLogs', initialLog, 'team'); }
        localStorage.setItem('erp_pmLaborLogs', JSON.stringify(pmLaborLogs));

        e.target.closest('.modal-overlay').remove();
        showToast('Đã đăng ký tổ đội mới: ' + newTeam.name, 'success');
        if (typeof renderQuanLyDuAn === 'function') renderQuanLyDuAn();
    };

