    window.erpApp.pmSaveEquipment = async (e, editCode = null) => {
        e.preventDefault();
        const form = e.target;
        const formData = new FormData(form);
        const cleanNum = (str) => window.erpApp.parseVND(str);

        if (editCode) {
            const idx = pmEquipment.findIndex(item => item.code === editCode);
            if (idx !== -1) {
                pmEquipment[idx].operator = formData.get('operator');
                pmEquipment[idx].fuelType = formData.get('fuelType');
                pmEquipment[idx].fuelNorm = cleanNum(formData.get('fuelNorm'));
                pmEquipment[idx].internalShiftRate = cleanNum(formData.get('internalShiftRate'));
                pmEquipment[idx].ownership = formData.get('ownership');
                pmEquipment[idx].status = formData.get('status');

                // 🔄 Sync status with Master Registry
                const vmVehicles = window.vmVehicles || [];
                const vIdx = vmVehicles.findIndex(v => v.id === editCode);
                if (vIdx !== -1) {
                    const newStatus = formData.get('status');
                    if (newStatus === 'dang-hoat-dong') { vmVehicles[vIdx].status = 'Đang đi'; }
                    else if (newStatus === 'dang-bao-tri') { vmVehicles[vIdx].status = 'Bảo trì'; }

                    if (window.CrudSync) { await window.CrudSync.saveItem('vmVehicles', vmVehicles[vIdx], 'id'); }
                    localStorage.setItem('erp_vmVehicles', JSON.stringify(vmVehicles));
                }

                if (window.CrudSync) { await window.CrudSync.saveItem('pmEquipment', pmEquipment[idx], 'code'); }
                localStorage.setItem('erp_pmEquipment', JSON.stringify(pmEquipment));
            }
        } else {
            const id = formData.get('code');
            const vmVehicles = window.vmVehicles || [];
            const v = vmVehicles.find(item => item.id === id);
            if (v) {
                const newEq = {
                    id: 'EQ-' + Math.random().toString(36).substr(2, 5).toUpperCase(),
                    projectId: pmActiveProjectId,
                    name: v.name,
                    type: v.type || v.model || 'Thiết bị',
                    code: v.id,
                    fuelType: formData.get('fuelType'),
                    fuelNorm: cleanNum(formData.get('fuelNorm')),
                    internalShiftRate: cleanNum(formData.get('internalShiftRate')),
                    status: 'dang-hoat-dong',
                    operator: formData.get('operator'),
                    ownership: formData.get('ownership') || 'Xe nhà',
                    maintCost: cleanNum(formData.get('maintCost')),
                    hours: 0
                };
                pmEquipment.unshift(newEq);

                v.status = 'Đang đi';
                v.location = pmActiveProjectId;

                if (window.CrudSync) {
                    await window.CrudSync.saveItem('pmEquipment', newEq, 'code');
                    await window.CrudSync.saveItem('vmVehicles', v, 'id');
                }
                localStorage.setItem('erp_pmEquipment', JSON.stringify(pmEquipment));
                localStorage.setItem('erp_vmVehicles', JSON.stringify(vmVehicles));
            }
        }

        form.closest('.modal-overlay').remove();
        showToast(editCode ? 'Cập nhật thiết bị thành công!' : 'Điều động thiết bị thành công!', 'success');

        if ((window.erpApp.currentPage === 'quan-ly-du-an' || window.erpApp.currentPage === 'van-hanh') && pmActiveTab === 'equipment') {
            if (typeof renderQuanLyDuAn === 'function') renderQuanLyDuAn();
        }
    };

    window.erpApp.pmOpenDetailedEquipmentReport = (projectId) => {
        const project = pmProjects.find(p => p.id === projectId);
        if (!project) { return; }

        const equipment = pmEquipment.filter(e => e.projectId === projectId);
        const logs = pmMachineLogs.filter(l => l.projectId === projectId);

        const overlay = document.createElement('div');
        overlay.className = 'modal-overlay';
        overlay.style = 'background:rgba(15,23,42,0.6); backdrop-filter:blur(5px); position:fixed; top:0; left:0; width:100%; height:100%; z-index:9999; display:flex; align-items:center; justify-content:center;';

        const tableRows = equipment.map(e => {
            const eqLogs = logs.filter(l => l.equipmentId === e.id);
            const totalHours = eqLogs.reduce((sum, l) => sum + (parseFloat(l.morningHours) || 0) + (parseFloat(l.afternoonHours) || 0), 0);
            const totalFuel = eqLogs.reduce((sum, l) => sum + (parseFloat(l.actualFuel) || 0), 0);

            return `
                <tr style="border-bottom:1px solid #f1f5f9;">
                    <td style="padding:15px; font-weight:800; color:#1e293b;">${e.code}</td>
                    <td style="padding:15px;">
                        <div style="font-weight:700; color:#475569;">${e.name}</div>
                        <div style="font-size:10px; color:#94a3b8; text-transform:uppercase;">${e.type}</div>
                    </td>
                    <td style="padding:15px; text-align:right; font-weight:700;">${totalHours.toLocaleString('vi-VN')} h</td>
                    <td style="padding:15px; text-align:right;">${totalFuel.toLocaleString('vi-VN')} L</td>
                    <td style="padding:15px; text-align:right; color:#3b82f6; font-weight:800;">${window.erpApp.formatValue((totalHours / 8) * (parseFloat(e.internalShiftRate) || 2500000))} đ</td>
                </tr>
            `;
        }).join('');

        overlay.innerHTML = `
            <div class="modal-content" style="width:900px; background:#fff; border-radius:32px; overflow:hidden; box-shadow:0 30px 60px -12px rgba(0,0,0,0.3); animation:modalPop 0.3s ease-out;">
                <div style="padding:32px; background:#1e293b; color:#fff; display:flex; justify-content:space-between; align-items:center;">
                    <h2 style="margin:0; font-size:20px; font-weight:900;">Báo cáo Thiết bị: ${project.name}</h2>
                    <button onclick="this.closest('.modal-overlay').remove()" style="background:rgba(255,255,255,0.1); border:none; color:#fff; width:40px; height:40px; border-radius:12px; cursor:pointer;"><span class="material-icons-outlined">close</span></button>
                </div>
                <div style="padding:32px; max-height:60vh; overflow-y:auto;">
                    <table style="width:100%; border-collapse:collapse; font-size:13px;">
                        <thead style="cursor: default; user-select: none;">
                            <tr style="text-align:left; color:#94a3b8; border-bottom:2px solid #f1f5f9;">
                                <th style="padding:15px;">Mã số</th>
                                <th style="padding:15px;">Thiết bị</th>
                                <th style="padding:15px; text-align:right;">Tổng giờ (H)</th>
                                <th style="padding:15px; text-align:right;">Nhiên liệu (L)</th>
                                <th style="padding:15px; text-align:right;">Khấu hao nội bộ</th>
                            </tr>
                        </thead>
                        <tbody>${tableRows}</tbody>
                    </table>
                </div>
                <div style="padding:24px 32px; background:#f8fafc; border-top:1px solid #f1f5f9; text-align:right;">
                    <button onclick="this.closest('.modal-overlay').remove()" style="padding:12px 32px; border-radius:16px; border:1px solid #e2e8f0; background:#fff; font-weight:800; cursor:pointer;">Đóng</button>
                </div>
            </div>
        `;
        document.body.appendChild(overlay);
    };











