    window.erpApp.saveProjectData = function () {
        const id = document.getElementById('editProjectId').value;
        const projects = typeof pmProjects !== 'undefined' ? pmProjects : [];
        const index = projects.findIndex(p => p.id === id);

        if (index === -1) {
            showToast('Không tìm thấy dự án để cập nhật!', 'error');
            return;
        }

        const oldName = projects[index].name;
        const name = document.getElementById('editProjectName').value.trim();
        const rawSigningDate = document.getElementById('editProjectSigningDate').value.trim();
        const rawStartDate = document.getElementById('editProjectStartDate').value.trim();
        const rawEndDate = document.getElementById('editProjectEndDate').value.trim();

        const acceptanceDateEl = document.getElementById('editProjectAcceptanceDate');
        const rawAcceptanceDate = acceptanceDateEl ? acceptanceDateEl.value.trim() : '';

        const warrantyPeriodEl = document.getElementById('editProjectWarrantyPeriod');
        const warrantyPeriod = warrantyPeriodEl ? (parseInt(warrantyPeriodEl.value) || null) : null;

        if (!name) {
            showToast('Tên dự án không được để trống!', 'error');
            return;
        }

        const parsedSigningDate = window.erpApp.parseInputDate(rawSigningDate);
        if (rawSigningDate && !window.erpApp.isValidDateString(parsedSigningDate)) {
            showToast('Ngày ký hợp đồng không hợp lệ! Định dạng yêu cầu: ngày/tháng/năm (ví dụ: 17/05/2026)', 'error');
            return;
        }

        const parsedStartDate = window.erpApp.parseInputDate(rawStartDate);
        if (rawStartDate && !window.erpApp.isValidDateString(parsedStartDate)) {
            showToast('Ngày bắt đầu không hợp lệ! Định dạng yêu cầu: ngày/tháng/năm', 'error');
            return;
        }

        const parsedEndDate = window.erpApp.parseInputDate(rawEndDate);
        if (rawEndDate && !window.erpApp.isValidDateString(parsedEndDate)) {
            showToast('Ngày kết thúc không hợp lệ! Định dạng yêu cầu: ngày/tháng/năm', 'error');
            return;
        }

        const parsedAcceptanceDate = window.erpApp.parseInputDate(rawAcceptanceDate);
        if (rawAcceptanceDate && !window.erpApp.isValidDateString(parsedAcceptanceDate)) {
            showToast('Ngày nghiệm thu hoàn thành không hợp lệ! Định dạng yêu cầu: ngày/tháng/năm', 'error');
            return;
        }

        const updatedProject = {
            ...projects[index],
            name: name,
            packageName: document.getElementById('editProjectPackageName').value.trim(),
            client: document.getElementById('editProjectClient').value,
            manager: document.getElementById('editProjectManager').value,
            budget: parseInt(document.getElementById('editProjectBudget').value.replace(/\./g, '')) || 0,
            type: document.getElementById('editProjectType').value,
            contractNo: document.getElementById('editProjectContractNo').value.trim(),
            signingDate: parsedSigningDate,
            location: document.getElementById('editProjectLocation').value,
            progress: parseInt(document.getElementById('editProjectProgressText').value) || 0,
            status: document.getElementById('editProjectStatus').value,
            warrantyPeriod: warrantyPeriod,
            acceptanceDate: document.getElementById('editProjectStatus').value === 'dang-thi-cong' ? null : parsedAcceptanceDate,
            startDate: parsedStartDate,
            executionTime: parseInt(document.getElementById('editProjectExecutionTime').value) || null,
            endDate: parsedEndDate
        };

        projects[index] = updatedProject;

        // Sync project name across archive documents when project tên đổi
        if (oldName && oldName !== updatedProject.name && typeof hoSoDocuments !== 'undefined') {
            hoSoDocuments.forEach(doc => {
                if (doc.project === oldName) {
                    doc.project = updatedProject.name;
                    if (window.CrudSync) { window.CrudSync.saveItem('hoSoDocuments', doc, 'id'); }
                }
            });
        }

        // Sync data
        if (window.CrudSync) {
            window.CrudSync.saveItem('pmProjects', updatedProject, 'id');
        }
        localStorage.setItem('erp_pmProjects', JSON.stringify(pmProjects));
        window.pmProjects = pmProjects; // SYNC TO GLOBAL

        showToast('Đã cập nhật dự án thành công!', 'success');
        document.getElementById('projectEditModal').remove();

        // Refresh views
        if (typeof window.erpApp.renderDanhSachDuAn === 'function') {
            window.erpApp.renderDanhSachDuAn();
        }
        if (typeof renderLuuTruHoSo === 'function') {
            renderLuuTruHoSo();
        }
    };

