                const mainDoc = (typeof hoSoDocuments !== 'undefined' ? hoSoDocuments : []).find(d => isProjectMatch(d.project, project) && d.category === 'hop-dong');
                const displayPackageName = (mainDoc && mainDoc.projectPublic) ? mainDoc.projectPublic : project.packageName;
                return displayPackageName ? `<div style="font-size: 14px; color: #475569; font-weight: 500; margin-bottom: 12px; display:flex; align-items:flex-start; gap:6px; line-height: 1.4;"><span style="color:#64748b; white-space:nowrap;">Tên dự án:</span> <span style="color: #1e293b; font-weight:700;">${displayPackageName}</span></div>` : '';
