    async function pmExecuteDeleteContract(id) {
        const pmContracts = window.pmContracts || [];
        const hoSoDocuments = window.hoSoDocuments || [];

        const index = pmContracts.findIndex(c => String(c.id).trim() === String(id).trim());
        if (index === -1) {
            console.error(`[PM Delete Legacy] Contract ID ${id} not found.`);
            return;
        }

        const contract = pmContracts[index];
        const linkedHsId = contract.linkedHsId;

        // 1. Remove from pmContracts
        pmContracts.splice(index, 1);
        if (window.CrudSync) {
            await window.CrudSync.deleteItem('pmContracts', id, 'id');
        }
        localStorage.setItem('erp_pmContracts', JSON.stringify(pmContracts));
        window.pmContracts = pmContracts;

        // 2. Unlink from hoSoDocuments if linked (DO NOT cascade delete archive documents)
        if (linkedHsId) {
            const hsDoc = hoSoDocuments.find(d => String(d.id).trim() === String(linkedHsId).trim());
            if (hsDoc) {
                hsDoc.linkedPmId = null;
                if (window.CrudSync) {
                    await window.CrudSync.saveItem('hoSoDocuments', hsDoc, 'id');
                }
                localStorage.setItem('erp_hoSoDocuments', JSON.stringify(hoSoDocuments));
                window.hoSoDocuments = hoSoDocuments;
                console.log(`[Unlinked Archive record] Set linkedPmId to null: ${linkedHsId}`);
            }
        }

        if (typeof window.erpApp.pmCloseDeleteContractModal === 'function') {
            window.erpApp.pmCloseDeleteContractModal();
        }
        showToast(`Đã xóa hợp đồng ${contract.title} và các dữ liệu liên kết.`, 'success');
        if (window.erpApp.notifyCRUD) {
            window.erpApp.notifyCRUD('Hợp đồng', 'delete', { name: contract.title, id: contract.id, page: 'quan-ly-du-an' });
        }
        renderQuanLyDuAn();

        if (typeof renderLuuTruHoSo === 'function') renderLuuTruHoSo();
    }

    function pmCloseDeleteContractModal() {
        const modal = document.getElementById('pmContractDeleteModal');
        if (modal) { modal.remove(); }
    }


    function pmSyncTasksFromVolumes() {
        const activeProjectId = pmActiveProjectId;
        console.log('Sync button clicked', { activeProjectId });

        if (!activeProjectId) {
            showToast('Vui lòng chọn một dự án trước khi đồng bộ!', 'warning');
            return;
        }

        if (typeof pmVolumes === 'undefined') {
            showToast('Dữ liệu Khối lượng chưa được tải, vui lòng đợi trong giây lát hoặc F5 lại trang.', 'error');
            return;
        }

        const projectVolumes = pmVolumes.filter(v => v.projectId === activeProjectId);

        // Collect all unique names and workItems from Volume tab
        const volumeNames = projectVolumes.map(v => (v.name || '').trim());
        const volumeWorkItems = projectVolumes.map(v => (v.workItem || '').trim());
        const allVolumeTitles = [...new Set([...volumeNames, ...volumeWorkItems])].filter(t => t.length > 0);
        const allVolumeTitlesUPPER = new Set(allVolumeTitles.map(t => t.toUpperCase()));

        const projectTasks = pmTasks.filter(t => t.projectId === activeProjectId);

        // 1. Identify tasks to DELETE (Exist in Progress but NOT in Volume)
        const tasksToDelete = projectTasks.filter(t => !allVolumeTitlesUPPER.has((t.title || '').trim().toUpperCase()));

        // 2. Identify titles to ADD (Exist in Volume but NOT in Progress)
        const existingTaskTitlesUPPER = new Set(projectTasks.map(t => (t.title || '').trim().toUpperCase()));
        const titlesToAdd = allVolumeTitles.filter(t => !existingTaskTitlesUPPER.has(t.trim().toUpperCase()));

        if (tasksToDelete.length === 0 && titlesToAdd.length === 0) {
            showToast('Dữ liệu Tiến độ đã đồng bộ khớp với Khối lượng!', 'info');
            return;
        }

        const confirmMsg = 'Hệ thống sẽ đồng bộ hóa bảng Tiến độ theo Khối lượng:<br>' +
            (tasksToDelete.length > 0 ? `- XÓA <strong>${tasksToDelete.length}</strong> công việc cũ (không còn trong Khối lượng).<br>` : '') +
            (titlesToAdd.length > 0 ? `- THÊM <strong>${titlesToAdd.length}</strong> công việc mới.<br>` : '') +
            'Bạn có chắc chắn muốn thực hiện?';

        window.erpApp.showConfirm(
            'Đồng bộ Tiến độ - Khối lượng',
            confirmMsg,
            function () {
                showToast('Đang thực hiện đồng bộ sạch...', 'info');

                // Execute deletions
                tasksToDelete.forEach(task => {
                    const idx = pmTasks.findIndex(t => t.id === task.id);
                    if (idx !== -1) { pmTasks.splice(idx, 1); }
                    if (window.CrudSync) { window.CrudSync.deleteItem('pmTasks', task.id); }
                    console.log('Deleted obsolete task:', task.title);
                });

                // Execute additions
                titlesToAdd.forEach((title, index) => {
                    const newTask = {
                        id: 'WBS-' + (Date.now() + index).toString().slice(-6),
                        projectId: activeProjectId,
                        parentId: '',
                        title: title,
                        weight: 0,
                        progress: 0,
                        startDate: new Date().toISOString().split('T')[0],
                        duration: 7,
                        endDate: new Date(Date.now() + 7 * 86400000).toISOString().split('T')[0]
                    };
                    pmTasks.push(newTask);
                    if (window.CrudSync) { window.CrudSync.saveItem('pmTasks', newTask); }
                    console.log('Added new task:', title);
                });

                localStorage.setItem('erp_pmTasks', JSON.stringify(pmTasks));
                window.pmTasks = pmTasks;

                showToast(`Đồng bộ hoàn tất! (Xóa: ${tasksToDelete.length}, Thêm: ${titlesToAdd.length})`, 'success');

                // Force re-render
                if (typeof renderQuanLyDuAn === 'function') {
                    console.log('Re-rendering module...');
                    renderQuanLyDuAn();
                }
            }
        );
    }

