    function pmHandleDashboardAlert(actionStr) {
        if (!actionStr) { return; }
        let tab = actionStr;
        let contractId = null;
        if (actionStr.includes(':')) {
            const parts = actionStr.split(':');
            tab = parts[0];
            contractId = parts[1];
        }
        pmActiveTab = tab;
        if (typeof renderQuanLyDuAn === 'function') {
            renderQuanLyDuAn();
        }
        if (contractId) {
            setTimeout(() => {
                const row = document.querySelector(`tr[data-warranty-contract-id="${contractId}"]`);
                if (row) {
                    row.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    row.style.transition = 'background-color 0.5s ease';
                    row.style.backgroundColor = '#fef08a'; // yellow highlight
                    setTimeout(() => {
                        row.style.backgroundColor = '';
                    }, 3000);
                }
            }, 200);
        }
    }

    function syncPmWarningsToNotifications(project, warnings) {
        if (!warnings || warnings.length === 0) { return; }

        // Use a unique key for each project to track sent notifications
        const sentKey = `erp_pm_notifs_sent_${project.id}`;
        let sentNotifs = [];
        try {
            sentNotifs = JSON.parse(localStorage.getItem(sentKey) || '[]');
        } catch (e) {
            sentNotifs = [];
        }

        let hasNew = false;
        warnings.forEach(w => {
            // Only sync "real" warnings (not the "stable" green one)
            if (w.icon === 'check_circle' || w.color === 'green') { return; }

            const notifTitle = `[Dự án ${project.id}] ${w.title}`;
            const notifKey = `${w.title}:${w.desc}`; // unique identifier for this warning

            // Check if this specific warning content has already been sent
            if (!sentNotifs.includes(notifKey)) {
                window.erpApp.addNotification(
                    notifTitle,
                    w.icon,
                    w.color,
                    { page: 'quan-ly-du-an', module: 'Quản lý dự án', projectId: project.id }
                );
                sentNotifs.push(notifKey);
                hasNew = true;
            }
        });

        if (hasNew) {
            // Keep a reasonably sized history of sent notifications
            if (sentNotifs.length > 50) { sentNotifs = sentNotifs.slice(-50); }
            localStorage.setItem(sentKey, JSON.stringify(sentNotifs));
        }
    }

