    window.erpApp.syncFuelPrices = async () => {
        showToast('Đang kết nối tới Petrolimex...', 'info');
        // Simulated delay for better UX
        await new Promise(r => setTimeout(r, 1500));

        // Data obtained from browser subagent scrape on 2026-04-26
        window.pmFuelPrices = {
            'dau-do-0001sv': { name: 'Dầu DO 0,001S-V', price: 27950, unit: 'đ/lít', lastUpdated: new Date().toLocaleDateString('vi-VN'), source: 'Petrolimex' },
            'dau-do-005sii': { name: 'Dầu DO 0,05S-II', price: 26690, unit: 'đ/lít', lastUpdated: new Date().toLocaleDateString('vi-VN'), source: 'Petrolimex' },
            'xang-ron95v': { name: 'Xăng RON 95-V', price: 23820, unit: 'đ/lít', lastUpdated: new Date().toLocaleDateString('vi-VN'), source: 'Petrolimex' },
            'lastUpdate': new Date().toISOString().split('T')[0]
        };
        // Backwards compatibility for legacy diesel_V key if used
        window.pmFuelPrices.diesel_V = window.pmFuelPrices['dau-do-0001sv'];

        localStorage.setItem('erp_pmFuelPrices', JSON.stringify(window.pmFuelPrices));

        showToast('Cập nhật giá nhiên liệu Petrolimex thành công!', 'success');

        const activeProject = pmProjects.find(p => p.id === pmActiveProjectId);
        if (activeProject) {
            const container = document.getElementById('pmEquipmentContent');
            if (container) { container.innerHTML = renderPmEquipment(activeProject); }
        }
    };

