    window.erpApp.pmSaveMachineLog = async (e, editId) => {
        e.preventDefault();
        const form = e.target;
        const formData = new FormData(form);

        const currentProjectId = pmActiveProjectId || window.erpApp.pmActiveProjectId || 'PJ-003';

        const logData = {
            id: editId || 'ML-' + Date.now(),
            projectId: currentProjectId,
            equipmentId: formData.get('equipmentId'),
            date: formData.get('date'),
            morningHours: window.erpApp.parseVND(formData.get('morningHours')),
            afternoonHours: window.erpApp.parseVND(formData.get('afternoonHours')),
            actualFuel: window.erpApp.parseVND(formData.get('actualFuel')),
            startKm: parseFloat(formData.get('startKm')) || 0,
            endKm: parseFloat(formData.get('endKm')) || 0,
            paidAmount: window.erpApp.parseVND(formData.get('paidAmount')),
            workNotes: formData.get('workNotes')
        };

        if (editId) {
            const idx = pmMachineLogs.findIndex(l => l.id === editId);
            if (idx !== -1) { pmMachineLogs[idx] = logData; }
        } else {
            pmMachineLogs.push(logData);
        }

        // Update equipment total hours
        const eq = pmEquipment.find(e => e.id === logData.equipmentId);
        if (eq) {
            const logsForEq = pmMachineLogs.filter(l => l.equipmentId === eq.id);
            eq.hours = logsForEq.reduce((sum, l) => sum + (l.morningHours + l.afternoonHours), 0);
            if (window.CrudSync) { await window.CrudSync.saveItem('pmEquipment', eq, 'id'); }
        }

        // Automatic Finance Record for Fuel if actualFuel provided
        if (logData.actualFuel > 0) {
            const fuelKey = eq.fuelType || 'diesel_V';
            const priceData = pmFuelPrices[fuelKey] || pmFuelPrices['dau-do-0001sv'] || 27000;
            const fuelPrice = parseFloat(priceData.price || priceData || 27000);

            const financeRecord = {
                id: 'TC-FUEL-' + logData.id,
                projectId: pmActiveProjectId,
                date: logData.date,
                type: 'chi',
                category: 'Máy thi công',
                content: `Chi phí nhiên liệu: ${eq.code} (${logData.actualFuel} Lít x ${window.erpApp.formatValue(fuelPrice)} đ)`,
                amount: (parseFloat(logData.actualFuel) || 0) * fuelPrice,
                quantity: logData.actualFuel,
                unit: 'Lít',
                price: fuelPrice,
                workItem: 'Cung cấp nhiên liệu'
            };

            // Avoid duplicate finance records for the same log
            const existingIdx = pmFinanceRecords.findIndex(r => r.id === financeRecord.id);
            if (existingIdx !== -1) {
                pmFinanceRecords[existingIdx] = financeRecord;
            } else {
                pmFinanceRecords.push(financeRecord);
            }
            if (window.CrudSync) { await window.CrudSync.saveItem('pmFinanceRecords', financeRecord, 'id'); }
        }

        if (window.CrudSync) { await window.CrudSync.saveItem('pmMachineLogs', logData, 'id'); }
        localStorage.setItem('erp_pmMachineLogs', JSON.stringify(pmMachineLogs));
        localStorage.setItem('erp_pmEquipment', JSON.stringify(pmEquipment));
        localStorage.setItem('erp_pmFinanceRecords', JSON.stringify(pmFinanceRecords));

        showToast('Đã lưu nhật ký ca máy.');
        form.closest('.modal-overlay').remove();

        const activeProject = pmProjects.find(p => p.id === currentProjectId);
        if (activeProject) {
            const container = document.getElementById('pmEquipmentContent');
            if (container) { container.innerHTML = renderPmEquipment(activeProject); }
        }
    };

    window.erpApp.pmDeleteMachineLog = (id) => {
        window.erpApp.showConfirm(
            'Xác nhận xóa',
            'Bạn có chắc chắn muốn xóa nhật ký này?',
            async function () {
                const idx = pmMachineLogs.findIndex(l => l.id === id);
                if (idx !== -1) {
                    const eqId = pmMachineLogs[idx].equipmentId;
                    pmMachineLogs.splice(idx, 1);

                    // Recalculate hours
                    const eq = pmEquipment.find(e => e.id === eqId);
                    if (eq) {
                        const logsForEq = pmMachineLogs.filter(l => l.equipmentId === eq.id);
                        eq.hours = logsForEq.reduce((sum, l) => sum + (l.morningHours + l.afternoonHours), 0);
                        if (window.erpApp && window.erpApp._setData) {
                            window.erpApp._setData('pmEquipment', pmEquipment);
                        }
                    }

                    localStorage.setItem('erp_pmMachineLogs', JSON.stringify(pmMachineLogs));
                    if (window.erpApp && window.erpApp._setData) {
                        window.erpApp._setData('pmMachineLogs', pmMachineLogs);
                    }

                    if (window.CrudSync) { await window.CrudSync.deleteItem('pmMachineLogs', id, 'id'); }
                    window.erpApp.showToast('Đã xóa nhật ký.');

                    const activeProject = pmProjects.find(p => p.id === pmActiveProjectId);
                    if (activeProject) {
                        const container = document.getElementById('pmEquipmentContent');
                        if (container) { container.innerHTML = renderPmEquipment(activeProject); }
                    }
                }
            }
        );
    };

