    window.erpApp.pmSaveMaintenance = async (e, editId) => {
        e.preventDefault();
        const form = e.target;
        const formData = new FormData(form);
        const cleanNum = (str) => window.erpApp.parseVND(str);

        const currentProjectId = pmActiveProjectId || window.erpApp.pmActiveProjectId;

        const logData = {
            id: editId || 'MNT-' + Date.now(),
            projectId: currentProjectId,
            equipmentId: formData.get('equipmentId'),
            date: formData.get('date'),
            type: formData.get('type'),
            cost: cleanNum(formData.get('cost')),
            paidAmount: cleanNum(formData.get('paidAmount')),
            content: formData.get('content')
        };

        if (editId) {
            const idx = pmMaintenanceLogs.findIndex(l => l.id === editId);
            if (idx !== -1) { pmMaintenanceLogs[idx] = logData; }
        } else {
            pmMaintenanceLogs.push(logData);
        }

        // --- SYNC TO VM MODULE (Vehicle/Equipment Management) ---
        try {
            const eq = pmEquipment.find(e => e.id === logData.equipmentId);
            const project = pmProjects.find(p => p.id === logData.projectId);

            if (eq && eq.code) {
                const vId = eq.code;
                const vmLog = {
                    id: logData.id,
                    vId: vId,
                    desc: logData.content,
                    projectName: project ? project.name : 'Dự án (N/A)',
                    type: logData.type,
                    date: logData.date.split('-').reverse().join('/'),
                    odo: 0,
                    cost: logData.cost,
                    status: 'Hoàn thành'
                };

                if (typeof vmMaintenance !== 'undefined') {
                    const vIdx = vmMaintenance.findIndex(m => m.id === logData.id);
                    if (vIdx !== -1) { vmMaintenance[vIdx] = vmLog; }
                    else { vmMaintenance.push(vmLog); }

                    localStorage.setItem('erp_vmMaintenance', JSON.stringify(vmMaintenance));
                    if (window.CrudSync) { await window.CrudSync.saveItem('vmMaintenance', vmLog, 'id'); }
                }
            }
        } catch (syncErr) {
            console.error('Error syncing maintenance to VM module:', syncErr);
        }

        if (window.CrudSync) { await window.CrudSync.saveItem('pmMaintenanceLogs', logData, 'id'); }
        localStorage.setItem('erp_pmMaintenanceLogs', JSON.stringify(pmMaintenanceLogs));

        form.closest('.modal-overlay').remove();
        renderQuanLyDuAn();
        showToast('Đã lưu thông tin bảo trì và đồng bộ hệ thống.', 'success');
    };

    window.erpApp.pmDeleteMaintenance = (id) => {
        window.erpApp.showConfirm(
            'Xác nhận xóa',
            'Bạn có chắc chắn muốn xóa bản ghi bảo trì này?',
            async function () {
                const idx = pmMaintenanceLogs.findIndex(l => l.id === id);
                if (idx !== -1) {
                    pmMaintenanceLogs.splice(idx, 1);

                    if (window.erpApp && window.erpApp._setData) {
                        window.erpApp._setData('pmMaintenanceLogs', pmMaintenanceLogs);
                    } else {
                        localStorage.setItem('erp_pmMaintenanceLogs', JSON.stringify(pmMaintenanceLogs));
                        if (window.CrudSync) { await window.CrudSync.deleteItem('pmMaintenanceLogs', id); }
                    }

                    // Sync deletion to VM
                    if (typeof vmMaintenance !== 'undefined') {
                        const vIdx = vmMaintenance.findIndex(m => m.id === id);
                        if (vIdx !== -1) {
                            vmMaintenance.splice(vIdx, 1);
                            if (window.erpApp && window.erpApp._setData) {
                                window.erpApp._setData('vmMaintenance', vmMaintenance);
                            } else {
                                localStorage.setItem('erp_vmMaintenance', JSON.stringify(vmMaintenance));
                                if (window.CrudSync) { await window.CrudSync.deleteItem('vmMaintenance', id); }
                            }
                        }
                    }

                    renderQuanLyDuAn();
                    window.erpApp.showToast('Đã xóa bản ghi bảo trì và cập nhật hệ thống.', 'success');
                }
            }
        );
    };

