    window.erpApp.pmDeleteVolume = (id) => {
        const currentUser = window.erpApp.getCurrentUser ? window.erpApp.getCurrentUser() : null;
        if (!currentUser || currentUser.role !== 'Admin') {
            window.erpApp.showToast('Chỉ Admin mới có quyền xóa dữ liệu khối lượng!', 'error');
            return;
        }

        window.erpApp.showDeleteConfirmation(
            'Bạn có chắc chắn muốn xóa hạng mục khối lượng này?',
            async function () {
                const idx = pmVolumes.findIndex(m => String(m.id) === String(id));
                if (idx !== -1) {
                    const item = pmVolumes[idx];
                    pmVolumes.splice(idx, 1);

                    localStorage.setItem('erp_pmVolumes', JSON.stringify(pmVolumes));
                    if (window.CrudSync) { await window.CrudSync.deleteItem('pmVolumes', id, 'id'); }

                    if (window.erpApp && window.erpApp._setData) {
                        window.erpApp._setData('pmVolumes', pmVolumes);
                    }

                    window.erpApp.showToast('Đã xóa hạng mục khối lượng.');

                    // Trigger Notification
                    if (window.erpApp.notifyCRUD) {
                        window.erpApp.notifyCRUD('Khối lượng', 'delete', {
                            name: item.name,
                            page: 'quan-ly-du-an',
                            module: 'Khối lượng',
                            projectId: pmActiveProjectId
                        });
                    }

                    const activeProject = pmProjects.find(p => p.id === pmActiveProjectId);
                    if (activeProject) {
                        const vPanel = document.getElementById('pmVolumeContent');
                        if (vPanel) { vPanel.innerHTML = renderPmVolume(activeProject); }
                        const sPanel = document.getElementById('pmSettlementContent');
                        if (sPanel) { sPanel.innerHTML = renderPmSettlement(activeProject); }
                    }
                }
            }
        );
    };

    window.erpApp.pmClearAllVolumes = () => {
        if (!pmActiveProjectId) { return; }
        window.erpApp.showDeleteConfirmation(
            'BẠN CÓ CHẮC CHẮN MUỐN XÓA TẤT CẢ KHỐI LƯỢNG CỦA DỰ ÁN NÀY? Thao tác này sẽ xóa toàn bộ hạng mục đã nhập và không thể hoàn tác.',
            async function () {
                const volumesToDelete = pmVolumes.filter(v => v.projectId === pmActiveProjectId);
                if (volumesToDelete.length === 0) {
                    window.erpApp.showToast('Không có dữ liệu khối lượng để xóa.', 'info');
                    return;
                }

                window.erpApp.showToast(`Đang xử lý xóa ${volumesToDelete.length} hạng mục...`, 'info');

                // 1. Local update (FAST)
                const remainingVolumes = pmVolumes.filter(v => v.projectId !== pmActiveProjectId);
                pmVolumes.length = 0;
                remainingVolumes.forEach(v => pmVolumes.push(v));
                localStorage.setItem('erp_pmVolumes', JSON.stringify(pmVolumes));
                if (window.erpApp && window.erpApp._setData) {
                    window.erpApp._setData('pmVolumes', pmVolumes);
                }

                // Refresh UI immediately
                const activeProject = pmProjects.find(p => p.id === pmActiveProjectId);
                if (activeProject) {
                    const vPanel = document.getElementById('pmVolumeContent');
                    if (vPanel) { vPanel.innerHTML = renderPmVolume(activeProject); }
                    const sPanel = document.getElementById('pmSettlementContent');
                    if (sPanel) { sPanel.innerHTML = renderPmSettlement(activeProject); }
                }

                window.erpApp.showToast('Đã xóa khối lượng cục bộ. Đang đồng bộ với Cloud...', 'info');

                // 2. Cloud Sync in background
                try {
                    if (window.CrudSync) {
                        const deletePromises = volumesToDelete.map(v =>
                            window.CrudSync.deleteItem('pmVolumes', v.id, 'id').catch(err => console.warn(`Lỗi xóa item ${v.id}:`, err))
                        );
                        await Promise.all(deletePromises);
                    }
                    window.erpApp.showToast('Đã đồng bộ xóa toàn bộ dữ liệu thành công.', 'success');
                } catch (error) {
                    console.error('Lỗi đồng bộ xóa Cloud:', error);
                    window.erpApp.showToast('Lỗi đồng bộ Cloud. Dữ liệu đã được xóa tại máy này.', 'warning');
                }
            }
        );
    };



    window.erpApp.pmSaveVolume = async (e, editId = null) => {
        e.preventDefault();
        const form = e.target;
        const formData = new FormData(form);
        const cleanNum = (str) => window.erpApp.parseVND(str);

        const volumeData = {
            id: editId || formData.get('id'),
            projectId: pmActiveProjectId,
            volumeType: formData.get('volumeType') || 'contract',
            name: formData.get('name'),
            unit: formData.get('unit'),
            norm: cleanNum(formData.get('norm')),
            prevActual: cleanNum(formData.get('prevActual')),
            actual: cleanNum(formData.get('actual')),
            price: cleanNum(formData.get('price')),
            workItem: formData.get('workItem')
        };

        if (editId) {
            const idx = pmVolumes.findIndex(m => String(m.id) === String(editId));
            if (idx !== -1) { pmVolumes[idx] = { ...pmVolumes[idx], ...volumeData }; }
        } else {
            pmVolumes.unshift(volumeData);
        }

        if (window.CrudSync) { await window.CrudSync.saveItem('pmVolumes', volumeData, 'id'); }
        localStorage.setItem('erp_pmVolumes', JSON.stringify(pmVolumes));
        showToast(editId ? 'Đã cập nhật khối lượng' : 'Đã thêm khối lượng mới', 'success');
        const activeProject = pmProjects.find(p => p.id === pmActiveProjectId);
        if (activeProject) {
            const vPanel = document.getElementById('pmVolumeContent');
            if (vPanel) { vPanel.innerHTML = renderPmVolume(activeProject); }
            const sPanel = document.getElementById('pmSettlementContent');
            if (sPanel) { sPanel.innerHTML = renderPmSettlement(activeProject); }
        }

        // Trigger Notification
        window.erpApp.notifyCRUD('Khối lượng', editId ? 'update' : 'add', {
            name: volumeData.name,
            page: 'quan-ly-du-an',
            module: 'Khối lượng',
            projectId: pmActiveProjectId
        });

        form.closest('.modal-overlay').remove();
    };

    window.erpApp.pmHandleImportVolume = async (event) => {
        const file = event.target.files[0];
        if (!file) { return; }

        const activeProjectId = pmActiveProjectId;
        if (!activeProjectId) {
            showToast('Vui lòng chọn một dự án trước khi nhập Excel!', 'error');
            return;
        }

        const reader = new FileReader();
        reader.onload = async (e) => {
            try {
                const data = new Uint8Array(e.target.result);
                const workbook = XLSX.read(data, { type: 'array' });
                const firstSheetName = workbook.SheetNames[0];
                const worksheet = workbook.Sheets[firstSheetName];
                const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1 });

                // Skip header rows (assume first 1-2 rows are headers)
                // We expect columns: STT, Name, Unit, Norm, PrevActual, Actual, Price, WorkItem
                const importedItems = [];
                let currentWorkItem = 'CHƯA XÁC ĐỊNH';
                let dataStarted = false;

                for (let i = 0; i < jsonData.length; i++) {
                    const row = jsonData[i];
                    if (!row || row.length < 2) { continue; }

                    const stt = row[0];
                    const name = row[1] ? String(row[1]).trim() : '';

                    // Skip empty names
                    if (!name) { continue; }

                    // Detect where the data actually starts
                    if (!dataStarted) {
                        // Check if this row looks like the header row
                        if (name.toLowerCase().includes('tên công việc') || name.toLowerCase().includes('tên hạng mục')) {
                            dataStarted = true;
                            continue;
                        }
                        // Or check if STT is 1 or looks like KM... (for group headers before first item)
                        if (stt === 1 || stt === '1' || name.startsWith('KM') || name.toUpperCase() === name) {
                            // We might have found a group header or the first item
                            // If it has no volume data, it's probably a group header
                            const valCheck = window.erpApp.cleanNum(row[3]) + window.erpApp.cleanNum(row[4]) + window.erpApp.cleanNum(row[5]);
                            if (valCheck === 0) {
                                currentWorkItem = name;
                                dataStarted = true;
                                continue;
                            } else {
                                dataStarted = true;
                            }
                        } else {
                            continue; // Skip until data starts
                        }
                    }

                    // Column mapping based on the user's Excel (03.a/TT):
                    // 0: STT, 1: Name, 2: Unit, 3: Norm, 4: PrevActual, 5: Actual, 6: Cumulative, 7: Price
                    const unit = row[2] ? String(row[2]).trim() : '';
                    const norm = window.erpApp.cleanNum(row[3]);
                    const prevActual = window.erpApp.cleanNum(row[4]);
                    const actual = window.erpApp.cleanNum(row[5]);
                    const price = window.erpApp.cleanNum(row[7]);

                    // If this row has a name but no volume/unit data, treat it as a new WorkItem group
                    if (!unit && norm === 0 && actual === 0 && prevActual === 0) {
                        currentWorkItem = name;
                        continue;
                    }

                    importedItems.push({
                        id: 'VOL-IMP-' + Date.now() + i,
                        projectId: activeProjectId,
                        name: name,
                        unit: unit,
                        norm: norm,
                        prevActual: prevActual,
                        actual: actual,
                        price: price,
                        workItem: currentWorkItem,
                        index: i
                    });
                }

                if (importedItems.length === 0) {
                    window.erpApp.showToast('Không tìm thấy dữ liệu hợp lệ trong file Excel.', 'warning');
                    return;
                }

                // Show notification immediately after parsing
                window.erpApp.showToast(`Đã tìm thấy ${importedItems.length} hạng mục. Đang chờ xác nhận...`, 'info');

                window.erpApp.showConfirm(
                    'Xác nhận nhập Excel',
                    `Hệ thống tìm thấy ${importedItems.length} hạng mục. Bạn có muốn nhập vào dự án hiện tại?`,
                    async function () {
                        window.erpApp.showToast(`Đang nhập ${importedItems.length} hạng mục...`, 'info');

                        // Trigger System Notification at start
                        if (window.erpApp && window.erpApp.notifyCRUD) {
                            window.erpApp.notifyCRUD('Khối lượng', 'add', {
                                name: `Bắt đầu nhập ${importedItems.length} hạng mục từ Excel`,
                                page: 'quan-ly-du-an',
                                module: 'Khối lượng',
                                projectId: activeProjectId
                            });
                        }

                        // Offline-First: Save to local memory and localStorage immediately
                        importedItems.forEach(item => pmVolumes.push(item));
                        localStorage.setItem('erp_pmVolumes', JSON.stringify(pmVolumes));

                        // Refresh UI immediately so user sees the data
                        const activeProject = pmProjects.find(p => p.id === activeProjectId);
                        if (activeProject) {
                            const vPanel = document.getElementById('pmVolumeContent');
                            if (vPanel) { vPanel.innerHTML = renderPmVolume(activeProject); }
                            const sPanel = document.getElementById('pmSettlementContent');
                            if (sPanel) { sPanel.innerHTML = renderPmSettlement(activeProject); }
                        }

                        window.erpApp.showToast(`Đã lưu ${importedItems.length} hạng mục vào máy. Đang đồng bộ lên Cloud...`, 'info');

                        try {
                            // Cloud Sync in background
                            if (window.FireSync && window.FireSync.batchUpload) {
                                await window.FireSync.batchUpload('pmVolumes', importedItems, 'id');
                            } else {
                                const savePromises = importedItems.map(item =>
                                    window.CrudSync ? window.CrudSync.saveItem('pmVolumes', item, 'id') : Promise.resolve()
                                );
                                await Promise.all(savePromises);
                            }

                            window.erpApp.showToast(`Đã đồng bộ thành công ${importedItems.length} hạng mục lên Cloud.`, 'success');
                        } catch (saveError) {
                            console.error('Lỗi khi đồng bộ Cloud:', saveError);
                            window.erpApp.showToast('Đã lưu cục bộ. Đồng bộ Cloud sẽ thử lại sau.', 'warning');
                        }

                        // Trigger Notification
                        window.erpApp.notifyCRUD('Khối lượng', 'add', {
                            name: `Nhập Excel (${importedItems.length} hạng mục)`,
                            page: 'quan-ly-du-an',
                            module: 'Khối lượng',
                            projectId: activeProjectId
                        });
                    }
                );

            } catch (error) {
                console.error('pmHandleImportVolume error', error);
                showToast('Lỗi khi đọc file Excel. Vui lòng kiểm tra định dạng file.', 'error');
            } finally {
                event.target.value = ''; // Reset input
            }
        };
        reader.readAsArrayBuffer(file);
    };

    window.erpApp.pmHandleImportPayment = async (event) => {
        const file = event.target.files[0];
        if (!file) { return; }

        if (!pmActiveProjectId) {
            showToast('Vui lòng chọn dự án trước khi nhập!', 'error');
            return;
        }

        const reader = new FileReader();
        reader.onload = async (e) => {
            try {
                const data = new Uint8Array(e.target.result);
                const workbook = XLSX.read(data, { type: 'array' });
                const ws = workbook.Sheets[workbook.SheetNames[0]];
                const jsonData = XLSX.utils.sheet_to_json(ws, { header: 1 });

                const imported = [];
                // Expecting: STT | Nội dung | Ngày | Số tiền (Thực tế) | Trạng thái | Ghi chú
                for (let i = 1; i < jsonData.length; i++) {
                    const row = jsonData[i];
                    if (!row || row.length < 3) { continue; }

                    let rawDate = row[2];
                    let formattedDate = '';

                    if (typeof rawDate === 'number') {
                        const dateObj = XLSX.utils.format_cell({ v: rawDate, t: 'd' });
                        formattedDate = window.erpApp.formatDate(new Date(rawDate * 86400000 - 2209161600000));
                    } else if (rawDate) {
                        formattedDate = String(rawDate).trim();
                    } else {
                        formattedDate = window.erpApp.formatDate(new Date());
                    }

                    const val = window.erpApp.cleanNum(row[3]);
                    imported.push({
                        id: `PAY-IMP-${Date.now()}-${i}`,
                        projectId: pmActiveProjectId,
                        title: row[1] || `Đợt thanh toán ${i}`,
                        date: formattedDate,
                        plannedValue: val, // Assume same for planned/actual for now
                        actualValue: val,
                        status: row[4] || 'cho-duyet',
                        note: row[5] || ''
                    });
                }

                if (imported.length === 0) {
                    window.erpApp.showToast('Không tìm thấy dữ liệu thanh toán hợp lệ!', 'warning');
                    return;
                }

                window.erpApp.showConfirm(
                    'Nhập dữ liệu thanh toán',
                    `Tìm thấy ${imported.length} đợt thanh toán. Bạn có muốn nhập vào hệ thống?`,
                    async function () {
                        imported.forEach(item => pmPaymentMilestones.unshift(item));
                        localStorage.setItem('erp_pmPaymentMilestones', JSON.stringify(pmPaymentMilestones));

                        if (window.CrudSync) {
                            for (const item of imported) {
                                await window.CrudSync.saveItem('pmPaymentMilestones', item, 'id');
                            }
                        }

                        window.erpApp.showToast(`Đã nhập thành công ${imported.length} đợt thanh toán`, 'success');

                        const activeProject = pmProjects.find(p => p.id === pmActiveProjectId);
                        if (activeProject) {
                            const sPanel = document.getElementById('pmSettlementContent');
                            if (sPanel) { sPanel.innerHTML = renderPmSettlement(activeProject); }
                        }

                        window.erpApp.notifyCRUD('Thanh toán', 'add', {
                            name: `Nhập Excel (${imported.length} đợt)`,
                            page: 'quan-ly-du-an',
                            module: 'Thanh toán',
                            projectId: pmActiveProjectId
                        });
                    }
                );

            } catch (err) {
                console.error(err);
                showToast('Lỗi xử lý file Excel', 'error');
            } finally {
                event.target.value = '';
            }
        };
        reader.readAsArrayBuffer(file);
    };

