    window.erpApp.pmSavePayment = async (e, editId) => {
        e.preventDefault();
        const form = e.target;
        const formData = new FormData(form);

        const paymentData = {
            id: editId || `PAY-${Date.now()}`,
            projectId: pmActiveProjectId,
            title: formData.get('title'),
            date: formData.get('date'),
            plannedValue: window.erpApp.cleanNum(formData.get('plannedValue')),
            actualValue: window.erpApp.cleanNum(formData.get('actualValue')),
            status: formData.get('status'),
            note: formData.get('note')
        };

        if (editId) {
            const idx = pmPaymentMilestones.findIndex(m => String(m.id) === String(editId));
            if (idx !== -1) { pmPaymentMilestones[idx] = paymentData; }
        } else {
            pmPaymentMilestones.unshift(paymentData);
        }

        if (window.CrudSync) { await window.CrudSync.saveItem('pmPaymentMilestones', paymentData, 'id'); }
        localStorage.setItem('erp_pmPaymentMilestones', JSON.stringify(pmPaymentMilestones));

        showToast(editId ? 'Đã cập nhật thanh toán' : 'Đã thêm đợt thanh toán', 'success');

        const activeProject = pmProjects.find(p => p.id === pmActiveProjectId);
        if (activeProject) {
            const sPanel = document.getElementById('pmSettlementContent');
            if (sPanel) { sPanel.innerHTML = renderPmSettlement(activeProject); }
        }

        window.erpApp.notifyCRUD('Thanh toán', editId ? 'update' : 'add', {
            name: paymentData.title,
            page: 'quan-ly-du-an',
            module: 'Thanh toán',
            projectId: pmActiveProjectId
        });

        form.closest('.modal-overlay').remove();
    };

