    window.erpApp.pmExportEquipmentReport = (projectId) => {
        const project = pmProjects.find(p => p.id === projectId);
        if (!project) { return; }

        const equipment = pmEquipment.filter(e => e.projectId === projectId);
        const logs = pmMachineLogs.filter(l => l.projectId === projectId);

        const data = equipment.map(e => {
            const eqLogs = logs.filter(l => l.equipmentId === e.id);
            const totalHours = eqLogs.reduce((sum, l) => sum + (parseFloat(l.morningHours) || 0) + (parseFloat(l.afternoonHours) || 0), 0);
            const totalFuel = eqLogs.reduce((sum, l) => sum + (parseFloat(l.actualFuel) || 0), 0);

            const fuelKey = e.fuelType || 'diesel_V';
            const priceData = pmFuelPrices[fuelKey] || pmFuelPrices['dau-do-0001sv'] || 27000;
            const price = parseFloat(priceData.price || priceData || 27000);
            const fuelCost = totalFuel * price;
            const internalCost = (totalHours / 8) * (parseFloat(e.internalShiftRate) || 2500000);

            return {
                'Mã thiết bị': e.code,
                'Tên thiết bị': e.name,
                'Chủng loại': e.type,
                'Tổng giờ (h)': totalHours,
                'Nhiên liệu (L)': totalFuel,
                'Chi phí dầu (VNĐ)': fuelCost,
                'Khấu hao nội bộ (VNĐ)': internalCost
            };
        });

        if (data.length === 0) {
            showToast('Không có dữ liệu để xuất!', 'warning');
            return;
        }

        const ws = XLSX.utils.json_to_sheet(data);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "Bao-cao-thiet-bi");

        // Format column widths
        ws['!cols'] = [
            { wch: 15 }, { wch: 30 }, { wch: 20 }, { wch: 15 }, { wch: 15 }, { wch: 20 }, { wch: 20 }
        ];

        XLSX.writeFile(wb, `Bao_cao_thiet_bi_${project.name.replace(/\s+/g, '_')}_${new Date().toISOString().split('T')[0]}.xlsx`);
        showToast('Đã xuất báo cáo Excel thành công!', 'success');
    };

