    // ==========================================
    // Global Keyboard Shortcuts
    // ==========================================
    document.addEventListener('keydown', (e) => {
        // Handle Backspace for "Go Back"
        if (e.key === 'Backspace') {
            const activeEl = document.activeElement;
            const isInput = activeEl.tagName === 'INPUT' ||
                activeEl.tagName === 'TEXTAREA' ||
                activeEl.isContentEditable ||
                activeEl.closest('.ql-editor');

            const hasModal = document.querySelector('.modal-overlay');

            if (!isInput && !hasModal) {
                e.preventDefault();
                window.erpApp.goBack();
            }
        }

        if (e.key === 'Escape') {
            const overlays = document.querySelectorAll('.modal-overlay');
            if (overlays.length > 0) {
                // Remove the top-most (last added) overlay
                const topOverlay = overlays[overlays.length - 1];
                topOverlay.remove();
            }
        }
    });

    // --- Employment & Salary Synchronization Helpers ---
    window.erpApp.getSalarySettings = function (empId) {
        if (!empId) { return { base: 0, resp: 0, lunch: 0, phone: 0, fuel: 0, site: 0, housing: 0, child: 0, sunCoeff: 2.0, advance: 0, otherDeduct: 0 }; }

        let settings = salarySettings[empId];
        if (!settings) {
            settings = { base: 0, resp: 0, lunch: 0, phone: 0, fuel: 0, site: 0, housing: 0, child: 0, sunCoeff: 2.0, advance: 0, otherDeduct: 0 };
        }

        // Nếu lương chính trống, tự động tìm từ hợp đồng mới nhất
        if (!settings.base || settings.base === 0) {
            const empContracts = (contracts || []).filter(c => c.empId === empId);
            if (empContracts.length > 0) {
                // Sắp xếp theo ngày bắt đầu giảm dần (mới nhất lên đầu)
                const latest = empContracts.sort((a, b) => {
                    const dateA = new Date(a.startDate);
                    const dateB = new Date(b.startDate);
                    return dateB - dateA;
                })[0];

                if (latest && latest.salary) {
                    settings.base = latest.salary;
                }
            }
        }
        return settings;
    };

    window.erpApp.syncContractSalaryToSettings = function (empId, salary) {
        if (!empId) { return; }
        let settings = salarySettings[empId];
        if (!settings) {
            settings = { base: salary, resp: 0, lunch: 0, phone: 0, fuel: 0, site: 0, housing: 0, child: 0, sunCoeff: 2.0, advance: 0, otherDeduct: 0 };
        } else {
            settings.base = salary;
        }

        salarySettings[empId] = settings;
        localStorage.setItem('erp_salary_settings', JSON.stringify(salarySettings));
        if (window.CrudSync) {
            window.CrudSync.saveItem('erp_salary_settings', { id: empId, ...settings }, 'id');
        }
        console.log(`[Sync] Updated salary for ${empId} to ${salary}`);
    };



