        if (!url) { showToast('Vui lòng nhập đường link!', 'error'); urlEl.focus(); return; }
        try { new URL(url); } catch (e) { showToast('Đường link không hợp lệ!', 'error'); urlEl.focus(); return; }
        const name = (nameEl && nameEl.value.trim()) || url.split('/').filter(Boolean).pop() || 'Link file';
        tempHsFiles.push({ name: name, url: url, type: 'link', size: '' });
        const listEl = document.getElementById('hsFileList');
        if (listEl) { listEl.innerHTML = renderHsFileList(tempHsFiles, true); }
        urlEl.value = '';
        if (nameEl) nameEl.value = '';
        showToast('Đã thêm link: ' + name, 'success');
