    window.erpApp.previewHsFile = async (index, docId) => {
        let file;
        if (docId) {
            const doc = hoSoDocuments.find(d => d.id === docId);
            if (doc && doc.files && doc.files[index]) {
                file = doc.files[index];
            }
        } else {
            file = tempHsFiles[index];
        }
        if (!file) {
            showToast('Không tìm thấy file!');
            return;
        }
        if (!file.dataUrl && !file.url && window.FileStore && docId) {
            const restored = await window.FileStore.getFile('hoSoDocuments', docId, file.name);
            if (restored) {
                file.dataUrl = restored;
            }
        }
        if (file && (file.dataUrl || file.url)) {
            const href = file.dataUrl || file.url;
            if (file.url && (file.url.includes('drive.google.com') || file.url.includes('docs.google.com'))) {
                window.open(file.url, '_blank');
                return;
            }
            const fType = file.type || getHsFileTypeFromName(file.name);
            if (file.dataUrl && fType === 'pdf') {
                const win = window.open('', '_blank');
                win.document.write(`<iframe src="${href}" style="width:100%;height:100%;border:none;position:fixed;top:0;left:0"></iframe>`);
            } else if (file.dataUrl && fType === 'img') {
                const win = window.open('', '_blank');
                win.document.write(`<html><body style="margin:0;background:#000;display:flex;align-items:center;justify-content:center;min-height:100vh"><img src="${href}" style="max-width:100%;max-height:100vh;object-fit:contain"></body></html>`);
            } else if (file.url) {
                window.open(href, '_blank');
            } else {
                const win = window.open('', '_blank');
                win.document.write(`<html><head><title>${file.name}</title></head><body style="font-family:sans-serif;padding:40px;text-align:center"><h2>📄 ${file.name}</h2><p>File này không thể xem trước trực tiếp.<br>Bấm nút bên dưới để tải về.</p><a href="${href}" download="${file.name}" style="display:inline-block;margin-top:20px;padding:12px 24px;background:#2563EB;color:white;border-radius:8px;text-decoration:none;font-weight:600">⬇ Tải xuống</a></body></html>`);
            }
        } else {
            showToast('File này chưa có dữ liệu để xem trước.');
        }
    };

